_ALIASES: dict[str, str] | None = None
_NUMBER_RE = re.compile(r"[-+]?\d+(?:[.,]\d+)?")


def _compact(value: object) -> str:
    text = unicodedata.normalize("NFKC", str(value or "")).casefold()
    return "".join(ch for ch in text if ch.isalnum())


def _aliases() -> dict[str, str]:
    global _ALIASES
    if _ALIASES is None:
        result: dict[str, str] = {}
        for fish_id, row in FISH_THRESHOLDS.items():
            result[_compact(fish_id)] = fish_id
            result[_compact(row.get("name_zh", ""))] = fish_id
        _ALIASES = {key: value for key, value in result.items() if key}
    return _ALIASES


def resolve_fish_id(fish: object) -> str:
    raw = str(fish or "").strip()
    if not raw:
        return ""
    aliases = _aliases()
    direct = aliases.get(_compact(raw))
    if direct:
        return direct
    lowered = raw.casefold()
    for alias, fish_id in aliases.items():
        if len(alias) >= 3 and alias in _compact(lowered):
            return fish_id
    return ""


def _number(value: object) -> float | None:
    text = str(value or "").strip().replace(",", ".")
    match = _NUMBER_RE.search(text)
    if not match:
        return None
    try:
        number = float(match.group(0))
    except ValueError:
        return None
    if "kg" in text.casefold() or "\u5343\u514b" in text or "\u516c\u65a4" in text:
        number *= 1000.0
    return number if number >= 0 else None


LEVEL_SUPER = "\u8d85\u7ea7\u7a00\u6709"
LEVEL_STAR = "\u661f\u9c7c"
LEVEL_RARE = "\u7a00\u6709"
LEVEL_QUALIFIED = "\u8fbe\u6807"
LEVEL_COMMON = "\u666e\u901a"
LEVEL_UNKNOWN = "\u7ea7\u522b\u5f85\u786e\u8ba4"


def classify_fish_level(
    fish: object = "",
    weight_g: object = None,
    rarity: object = "",
    grade: object = "",
    flags: object = "",
) -> str:
    """Classify a live catch from explicit game metadata and local thresholds."""
    rarity_text = str(rarity or "").casefold().replace("-", "_")
    grade_text = str(grade or "").casefold().replace("-", "_")
    flags_text = str(flags or "").casefold()
    combined = " ".join((rarity_text, grade_text, flags_text))

    if any(token in combined for token in (
        "blue_crown", "blue crown", "bluecrown", "super_rare",
        "super rare", "ultra_rare", "ultra rare", "mythic",
        "\u8d85\u7ea7\u7a00\u6709", "\u84dd\u51a0",
    )):
        return LEVEL_SUPER
    if any(token in combined for token in (
        "star_fish", "star fish", "starfish", "star", "\u661f\u9c7c",
    )):
        return LEVEL_STAR

    explicit_rare = any(token in combined for token in (
        "rare", "trophy", "\u7a00\u6709",
    ))
    explicit_qualified = any(token in combined for token in (
        "qualified", "qualifying", "\u8fbe\u6807", "\u5408\u683c",
    ))
    explicit_common = any(token in combined for token in (
        "common", "\u666e\u901a", "\u672a\u8fbe\u6807", "\u4e0d\u8fbe\u6807",
    ))

    weight = _number(weight_g)
    fish_id = resolve_fish_id(fish)
    row = FISH_THRESHOLDS.get(fish_id) if fish_id else None
    if row and weight is not None:
        blue = _number(row.get("blue_crown_weight_g"))
        star = _number(row.get("star_weight_g"))
        qualified = _number(row.get("qualified_weight_g"))
        if blue is not None and weight >= blue:
            return LEVEL_SUPER
        if star is not None and weight >= star:
            return LEVEL_STAR
        if explicit_rare:
            return LEVEL_RARE
        if qualified is not None and weight >= qualified:
            return LEVEL_QUALIFIED
        return LEVEL_COMMON

    if explicit_rare:
        return LEVEL_RARE
    if explicit_qualified:
        return LEVEL_QUALIFIED
    if explicit_common or weight is not None:
        return LEVEL_COMMON
    return LEVEL_UNKNOWN if str(fish or "").strip() else ""


def compact_badge(value: object) -> str:
    text = str(value or "").strip()
    return {
        LEVEL_UNKNOWN: "\u5f85\u786e\u8ba4",
        LEVEL_SUPER: "\u8d85\u7a00\u6709",
        LEVEL_COMMON: "\u666e\u901a",
    }.get(text, text)
